import { afterEach, describe, expect, it, vi } from 'vitest'
import { ApiError } from './api-error'
import { HttpClient } from './http-client'

afterEach(() => {
  vi.unstubAllGlobals()
  vi.useRealTimers()
})

const response = (body: BodyInit | null, status = 200, headers?: HeadersInit) =>
  new Response(body, { status, headers })

describe('HttpClient', () => {
  it('serializes JSON and returns JSON', async () => {
    const fetchMock = vi.fn().mockResolvedValue(response('{"ok":true}'))
    vi.stubGlobal('fetch', fetchMock)

    await expect(
      new HttpClient().post('example', { name: 'test' }),
    ).resolves.toEqual({ ok: true })

    expect(fetchMock.mock.calls[0][1]).toMatchObject({
      body: '{"name":"test"}',
      method: 'POST',
    })
  })

  it('preserves FormData and handles no content', async () => {
    const form = new FormData()
    form.append('file', new Blob(['x']), 'x.txt')
    const fetchMock = vi.fn().mockResolvedValue(response(null, 204))
    vi.stubGlobal('fetch', fetchMock)

    await expect(new HttpClient().post('upload', form)).resolves.toBeUndefined()
    expect(fetchMock.mock.calls[0][1].body).toBe(form)
  })

  it.each([
    ['get', 'GET'],
    ['post', 'POST'],
    ['put', 'PUT'],
    ['patch', 'PATCH'],
    ['delete', 'DELETE'],
  ] as const)('uses %s requests', async (operation, method) => {
    const fetchMock = vi.fn().mockResolvedValue(response(null, 204))
    vi.stubGlobal('fetch', fetchMock)
    const client = new HttpClient()

    if (operation === 'get' || operation === 'delete') await client[operation]('example')
    else await client[operation]('example', { ok: true })

    expect(fetchMock.mock.calls[0][1].method).toBe(method)
  })

  it('returns non-JSON successful responses as text', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(response('plain text')))

    await expect(new HttpClient().get('health')).resolves.toBe('plain text')
  })

  it('normalizes Problem Details with request IDs', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(
        response(
          JSON.stringify({
            title: 'Request failed',
            detail: 'The requested operation failed.',
            status: 409,
            code: 'conflict',
          }),
          409,
          { 'x-request-id': 'request-123' },
        ),
      ),
    )

    await expect(new HttpClient().get('example')).rejects.toMatchObject({
      status: 409,
      message: 'The requested operation failed.',
      code: 'conflict',
      requestId: 'request-123',
    })
  })

  it('normalizes validation Problem Details', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(
        response(
          JSON.stringify({
            title: 'Validation failed',
            status: 400,
            errors: { name: ['Required'] },
          }),
          400,
        ),
      ),
    )

    await expect(new HttpClient().get('example')).rejects.toMatchObject({
      status: 400,
      fieldErrors: { name: ['Required'] },
    })
  })

  it('reports network failures', async () => {
    vi.stubGlobal('fetch', vi.fn().mockRejectedValue(new TypeError('offline')))

    await expect(new HttpClient().get('example')).rejects.toMatchObject({
      kind: 'network',
      message: 'A network error occurred.',
    } satisfies Partial<ApiError>)
  })

  it('reports timeout cancellation', async () => {
    vi.useFakeTimers()
    vi.stubGlobal(
      'fetch',
      vi.fn(
        (_url: string, init: RequestInit) =>
          new Promise((_resolve, reject) => {
            init.signal?.addEventListener('abort', () => reject(new Error('aborted')))
          }),
      ),
    )
    const request = new HttpClient().get('example', { timeoutMs: 1 })

    await vi.advanceTimersByTimeAsync(1)

    await expect(request).rejects.toMatchObject({ kind: 'timeout' })
  })

  it('reports caller cancellation', async () => {
    const controller = new AbortController()
    vi.stubGlobal(
      'fetch',
      vi.fn(
        (_url: string, init: RequestInit) =>
          new Promise((_resolve, reject) => {
            init.signal?.addEventListener('abort', () => reject(new Error('aborted')))
          }),
      ),
    )
    const request = new HttpClient().get('example', { signal: controller.signal })
    controller.abort()

    await expect(request).rejects.toMatchObject({ kind: 'aborted' })
  })
})

import { fireEvent, render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'
import { Alert, Badge, BrandMark, Button } from './common'
import { FileDropzone, FormField, Input, PasswordInput } from './forms'
import { StatCard, Stepper } from './navigation'
import { DataTable } from './tables'

describe('foundation components', () => {
  it('renders accessible actions and feedback', async () => {
    const user = userEvent.setup()
    const click = vi.fn()
    render(
      <>
        <Button loading onClick={click}>
          Save
        </Button>
        <Alert tone="danger">Problem</Alert>
        <BrandMark alt="Technical mark" />
      </>,
    )

    await user.click(screen.getByRole('button', { name: 'Save' }))

    expect(click).not.toHaveBeenCalled()
    expect(screen.getByRole('alert')).toHaveTextContent('Problem')
    expect(screen.getByAltText('Technical mark')).toBeInTheDocument()
  })

  it('renders Badge content with its selected tone', () => {
    render(<Badge tone="success">Published</Badge>)

    expect(screen.getByText('Published')).toHaveClass('bg-green-100')
  })

  it('associates a field and toggles password visibility', async () => {
    const user = userEvent.setup()
    render(
      <>
        <FormField label="Name" hint="Help" error="Required">
          <Input />
        </FormField>
        <PasswordInput aria-label="Password" />
      </>,
    )

    expect(screen.getByLabelText('Name')).toHaveAttribute('aria-invalid', 'true')
    await user.click(screen.getByRole('button', { name: 'Show password' }))
    expect(screen.getByLabelText('Password')).toHaveAttribute('type', 'text')
  })

  it('validates, selects, and removes dropped files', async () => {
    const user = userEvent.setup()
    const onChange = vi.fn()
    render(<FileDropzone accept=".zip" maxSizeBytes={10} onChange={onChange} />)
    const dropzone = screen.getByRole('button', {
      name: 'Drop a file here or select one',
    })

    fireEvent.drop(dropzone, {
      dataTransfer: { files: [new File(['zip'], 'submission.zip')] },
    })
    expect(screen.getByText('submission.zip')).toBeInTheDocument()
    expect(onChange).toHaveBeenLastCalledWith(expect.any(File))

    await user.click(screen.getByRole('button', { name: 'Remove file' }))
    expect(onChange).toHaveBeenLastCalledWith(undefined)

    fireEvent.drop(dropzone, {
      dataTransfer: { files: [new File(['text'], 'notes.txt')] },
    })
    expect(screen.getByRole('alert')).toHaveTextContent('File type is not accepted.')
  })

  it('identifies active steps, shows stats, and renders table states', () => {
    render(
      <>
        <Stepper steps={['One', 'Two']} activeIndex={1} />
        <StatCard label="Open" value="12" />
        <DataTable
          columns={[{ key: 'name', header: 'Name' }]}
          rows={[{ name: 'Sample row' }]}
        />
      </>,
    )

    expect(screen.getByText('2. Two')).toHaveAttribute('aria-current', 'step')
    expect(screen.getByText('Open')).toBeInTheDocument()
    expect(screen.getByRole('columnheader', { name: 'Name' })).toBeInTheDocument()
    expect(screen.getByRole('cell', { name: 'Sample row' })).toBeInTheDocument()
  })
})

import { render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { AdminLayout } from './AdminLayout'
import { AuthLayout } from './AuthLayout'

describe('foundation layouts', () => {
  it('renders AuthLayout title, description, branding, illustration, and content slots', () => {
    render(
      <AuthLayout
        title="Welcome"
        description="Use your account to continue."
        branding={<span>Custom brand</span>}
        illustration={<span>Illustration slot</span>}
      >
        <button type="button">Continue</button>
      </AuthLayout>,
    )

    expect(screen.getByRole('heading', { name: 'Welcome' })).toBeInTheDocument()
    expect(screen.getByText('Use your account to continue.')).toBeInTheDocument()
    expect(screen.getAllByText('Custom brand')).toHaveLength(2)
    expect(screen.getByText('Illustration slot')).toBeInTheDocument()
    expect(screen.getByRole('button', { name: 'Continue' })).toBeInTheDocument()
  })

  it('renders AdminLayout navigation, topbar controls, user, and content', () => {
    render(
      <AdminLayout user="Ada Lovelace">
        <h1>Dashboard content</h1>
      </AdminLayout>,
    )

    expect(screen.getByRole('navigation')).toBeInTheDocument()
    expect(screen.getByText('Contests')).toBeInTheDocument()
    expect(
      screen.getByRole('button', { name: 'Notifications' }),
    ).toBeInTheDocument()
    expect(screen.getByLabelText('Ada Lovelace')).toBeInTheDocument()
    expect(
      screen.getByRole('heading', { name: 'Dashboard content' }),
    ).toBeInTheDocument()
  })
})

import { render, screen } from '@testing-library/react'
import { RouterProvider } from 'react-router-dom'
import { describe, expect, it } from 'vitest'
import { createAppRouter } from './router'

describe('application routes', () => {
  it('renders the 404 page for unknown routes', async () => {
    const router = createAppRouter(false)
    await router.navigate('/missing')
    render(<RouterProvider router={router} />)

    expect(await screen.findByRole('heading', { name: '404' })).toBeInTheDocument()
  })

  it('registers /dev/ui only in development', async () => {
    const developmentRouter = createAppRouter(true)
    await developmentRouter.navigate('/dev/ui')
    render(<RouterProvider router={developmentRouter} />)
    expect(
      await screen.findByRole('heading', { name: 'Foundation catalog' }),
    ).toBeInTheDocument()

    const productionRouter = createAppRouter(false)
    await productionRouter.navigate('/dev/ui')
    render(<RouterProvider router={productionRouter} />)
    expect(await screen.findAllByRole('heading', { name: '404' })).toHaveLength(1)
  })
})

